import{_ as e,o,c as l,a2 as r}from"./chunks/framework.CZGNF-7T.js";const h=JSON.parse('{"title":"영업 조직 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/organization.md","filePath":"sales/organization.md","lastUpdated":1788879942000}'),i={name:"sales/organization.md"};function a(n,t,s,d,c,g){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="영업-조직-관리" tabindex="-1">영업 조직 관리 <a class="header-anchor" href="#영업-조직-관리" aria-label="Permalink to &quot;영업 조직 관리&quot;">​</a></h1><p>프로젝트에 투입되는 분양 대행사, 영업 본부/팀, 그리고 영업 상담사 및 팀장 등 인력을 3단계 계층 구조로 등록하고 계좌 정보와 3.3% 프리랜서 과세 유형, 필수 증빙 서류(등본, 통장 사본, 신분증, 위촉계약서, 각서 등)를 관리하는 기준 정보 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 영업 조직 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>분양 영업을 전담하는 조직 체계를 체계적으로 전산화합니다. 분양 대행사(<code>SalesAgency</code>)를 최상위로 두고 그 산하에 영업 본부 및 팀(<code>SalesTeam</code>)을 트리 형태로 구성하며, 각 팀에 소속되는 상담사 및 팀장(<code>SalesPerson</code>)을 등록합니다. 특히 수수료 이체 및 원천징수 신고를 위해 각 인력별 금융 계좌 정보와 과세 유형(3.3% 사업소득 프리랜서 여부)을 철저히 관리하며, 계약 체결 및 수수료 정산에 필요한 법적 증빙 서류(등본, 통장 사본, 신분증, 위촉계약서, 보안서약서 등)의 접수·열람·검증 체계를 지원합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>3단계 영업 조직 계층 관리</strong>: 대행사 ➔ 영업 본부/팀 ➔ 영업 인력(상담사)</li><li><strong>좌측 조직 트리뷰 연동</strong>: 대행사 또는 팀 선택 시 우측 명부에 해당 소속 인력만 즉시 필터링</li><li><strong>대행사 운영 형태 구분</strong>: 본사 직영 조직 또는 외부 전문 분양대행사 구분 관리</li><li><strong>프리랜서(3.3%) 세무 유형 설정</strong>: 사업소득세 원천징수 대상자 여부 등록</li><li><strong>금융 입금 계좌 관리</strong>: 주요 시중은행, 인터넷은행, 지방은행 셀렉터 및 계좌번호, 예금주 등록</li><li><strong>증빙 서류 접수 및 검증 체계</strong>: 주민등록등본, 통장 사본, 신분증, 영업 위촉계약서, 보안서약서 등 파일(PDF, 이미지) 업로드 및 관리자 검증</li><li><strong>모바일 원클릭 열람 및 공유</strong>: 모바일 앱(Flutter)에서 상담사별 제출 서류 확인, PDF/이미지 즉시 열람, 카카오톡/이메일 공유 지원</li><li><strong>재직 상태 관리</strong>: 위촉, 재직, 휴직, 해촉(퇴사) 상태 관리</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-좌측-영업-조직-계층-트리뷰-agencyteamtree" tabindex="-1">1. 좌측 영업 조직 계층 트리뷰 (AgencyTeamTree) <a class="header-anchor" href="#_1-좌측-영업-조직-계층-트리뷰-agencyteamtree" aria-label="Permalink to &quot;1. 좌측 영업 조직 계층 트리뷰 (AgencyTeamTree)&quot;">​</a></h3><p>프로젝트에 등록된 대행사와 산하 팀 구조를 한눈에 볼 수 있는 트리 뷰입니다.</p><ul><li><strong>[대행사 추가] 버튼</strong>: 상단 <code>+</code> 버튼으로 신규 대행사 등록</li><li><strong>대행사 아이템</strong>: <ul><li>직영/외주 뱃지 표출</li><li>수정(<code>[연필]</code>), 삭제(<code>[휴지통]</code>), 하위 팀 추가(<code>[+]</code>) 버튼 제공</li></ul></li><li><strong>하위 팀 아이템</strong>: <ul><li>팀 소속 인원수 뱃지 표출</li><li>클릭 시 해당 팀이 강조 표시되며 우측 인력 명부가 자동 필터링</li><li>수정 및 삭제 버튼 제공</li></ul></li></ul><h3 id="_2-우측-영업-인력-명부-personlist" tabindex="-1">2. 우측 영업 인력 명부 (PersonList) <a class="header-anchor" href="#_2-우측-영업-인력-명부-personlist" aria-label="Permalink to &quot;2. 우측 영업 인력 명부 (PersonList)&quot;">​</a></h3><p>선택된 대행사 또는 팀에 소속된 영업 인력의 상세 명단 테이블입니다.</p><ul><li><strong>상단 필터 및 제어 바</strong>: <ul><li>직책 필터 (전체, 분양상담사, 팀장, 본부장, 총괄본부장, 지원/기타)</li><li>재직 상태 필터 (전체, 재직, 휴직, 해촉)</li><li>성명/연락처/예금주 검색창</li><li><code>[신규 인력 등록]</code> 버튼 (<code>primary</code>)</li></ul></li><li><strong>인력 목록 테이블</strong>: <ul><li>소속 대행사 및 팀</li><li>직책 (상담사, 팀장, 본부장, 총괄 뱃지)</li><li>성명 (클릭 시 수정 모달 오픈)</li><li>연락처</li><li>소득 구분 (3.3% 프리랜서 뱃지)</li><li>정산 계좌 정보 (은행명, 계좌번호, 예금주)</li><li><strong>제출 서류</strong>: 제출된 서류 건수 뱃지 (<code>[📎 서류 N건]</code>), 클릭 시 전용 서류 관리 모달 호출</li><li>상태 (재직, 휴직, 해촉 뱃지)</li><li>관리 액션: 수정(<code>[연필]</code>) 및 삭제(<code>[휴지통]</code>) 버튼</li></ul></li></ul><h3 id="_3-입력-폼-모달-안내" tabindex="-1">3. 입력 폼 모달 안내 <a class="header-anchor" href="#_3-입력-폼-모달-안내" aria-label="Permalink to &quot;3. 입력 폼 모달 안내&quot;">​</a></h3><h4 id="_1-대행사-등록-모달-agencyformmodal" tabindex="-1">① 대행사 등록 모달 (AgencyFormModal) <a class="header-anchor" href="#_1-대행사-등록-모달-agencyformmodal" aria-label="Permalink to &quot;① 대행사 등록 모달 (AgencyFormModal)&quot;">​</a></h4><ul><li><strong>대행사명</strong> (필수): 회사 상호 또는 직영 사업단 명칭</li><li><strong>운영 형태</strong>: 직영 분양팀 또는 외주 대행사 선택</li><li><strong>대표자명 / 사업자등록번호 / 연락처 / 담당자 정보</strong></li><li><strong>계약 기간</strong>: 대행 계약 시작일 및 종료일 (<code>DatePicker</code>)</li></ul><h4 id="_2-영업-팀-등록-모달-teamformmodal" tabindex="-1">② 영업 팀 등록 모달 (TeamFormModal) <a class="header-anchor" href="#_2-영업-팀-등록-모달-teamformmodal" aria-label="Permalink to &quot;② 영업 팀 등록 모달 (TeamFormModal)&quot;">​</a></h4><ul><li><strong>소속 대행사</strong> (필수): 소속될 상위 대행사 선택</li><li><strong>상위 조직</strong>: 본부 산하 팀 구성 시 상위 본부 선택 (다단계 계층 지원)</li><li><strong>팀/조직명</strong> (필수): 예: &quot;분양 1본부&quot;, &quot;영업 2팀&quot;</li><li><strong>팀장 성명</strong>: 조직 책임자 성명</li></ul><h4 id="_3-영업-인력-등록-수정-모달-personformmodal" tabindex="-1">③ 영업 인력 등록/수정 모달 (PersonFormModal) <a class="header-anchor" href="#_3-영업-인력-등록-수정-모달-personformmodal" aria-label="Permalink to &quot;③ 영업 인력 등록/수정 모달 (PersonFormModal)&quot;">​</a></h4><ul><li><strong>소속 팀</strong> (필수): 배치될 영업 팀 선택</li><li><strong>성명</strong> (필수) 및 <strong>직책</strong> (상담사, 팀장, 본부장, 총괄본부장, 지원/기타)</li><li><strong>휴대전화</strong> (필수) 및 <strong>주민등록번호</strong> (원천세 신고 식별용)</li><li><strong>소득 구분</strong> (필수): <code>3.3% 사업소득 (프리랜서)</code>, <code>근로소득</code>, <code>사업자 (세금계산서)</code>, <code>기타</code></li><li><strong>정산 계좌 정보</strong>: 거래 은행 선택, 계좌번호, 예금주명</li><li><strong>증빙 서류 관리 바로가기</strong> (수정 시): 기존 인력 수정 모드 시 하단에 증빙 서류 현황 및 <code>[증빙 서류 관리]</code> 버튼 제공</li><li><strong>활동 및 재직 정보</strong>: 재직 상태, 위촉/입사일자 및 해촉/퇴사일자 (<code>DatePicker</code>)</li><li><strong>비고 / 특이사항</strong>: 추천인, 영업 경력 사항 등 메모</li></ul><h3 id="_4-증빙-서류-접수-및-관리-모달-persondocumentmodal" tabindex="-1">4. 증빙 서류 접수 및 관리 모달 (PersonDocumentModal) <a class="header-anchor" href="#_4-증빙-서류-접수-및-관리-모달-persondocumentmodal" aria-label="Permalink to &quot;4. 증빙 서류 접수 및 관리 모달 (PersonDocumentModal)&quot;">​</a></h3><p>영업 인력이 영업 활동 및 수수료 정산을 위해 제출한 각종 증빙 서류를 업로드하고 검증하는 전용 모달창입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">서류 구분</th><th style="text-align:center;">권장/필수 여부</th><th style="text-align:left;">세부 내용 및 활용처</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>주민등록등본/초본</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">본인 실명 확인 및 주소지 확인 (원천징수 영수증 발급용)</td></tr><tr><td style="text-align:left;"><strong>통장 사본 (계좌 사본)</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">수수료 정산 이체 시 명의 일치 확인</td></tr><tr><td style="text-align:left;"><strong>신분증 사본</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">주민등록번호 확인 및 신원 보증</td></tr><tr><td style="text-align:left;"><strong>영업 위촉계약서</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">분양 대행 수수료 지급 및 위촉 효력 입증 서류</td></tr><tr><td style="text-align:left;"><strong>각종 서약서/각서</strong></td><td style="text-align:center;">선택/권장</td><td style="text-align:left;">보안/비밀유지 서약서, 청렴이행각서 등 (세부 명칭 직접 기재 가능)</td></tr><tr><td style="text-align:left;"><strong>기타 증빙서류</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">사업자등록증 사본, 공인중개사 자격증, 경력증명서 등</td></tr></tbody></table><ul><li><strong>신규 서류 업로드</strong>: <ul><li>서류 구분 선택 후 필요 시 세부 명칭(예: &quot;보안서약서&quot;, &quot;청렴이행각서&quot;, &quot;사업자등록증&quot; 등) 입력</li><li>PDF, JPG, PNG, DOC/DOCX 등 서류 파일 선택 후 <code>[서류 등록]</code> 클릭 시 즉시 접수</li></ul></li><li><strong>제출 서류 목록 및 관리</strong>: <ul><li>서류 구분 뱃지, 서류명, 파일명 및 용량, 접수 일자 표시</li><li><strong>다운로드 / 열람</strong>: 파일명 또는 <code>[다운로드]</code> 아이콘 클릭 시 새 탭에서 즉시 열람 및 내려받기</li><li><strong>관리자 검증 (<code>verify</code>)</strong>: 서류 대조 후 <code>[검증]</code> 버튼 클릭 시 <code>검증완료</code> 상태로 변경되며 검증자 및 일시 기록 (언제든 <code>[검증취소]</code> 가능)</li><li><strong>서류 삭제</strong>: 잘못 접수된 서류는 <code>[삭제]</code> 아이콘으로 즉시 삭제 처리 (스토리지 파일 동시 정리)</li></ul></li></ul><h3 id="_5-모바일-앱-flutter-서류-열람-및-공유" tabindex="-1">5. 모바일 앱(Flutter) 서류 열람 및 공유 <a class="header-anchor" href="#_5-모바일-앱-flutter-서류-열람-및-공유" aria-label="Permalink to &quot;5. 모바일 앱(Flutter) 서류 열람 및 공유&quot;">​</a></h3><p>스마트폰 모바일 환경에서도 현장 관리자나 대행사 관계자가 상담사의 제출 서류를 즉시 확인하고 공유할 수 있습니다.</p><ul><li><strong>인력 카드 바로가기</strong>: 영업 조직 화면의 인력 카드에 <code>증빙 서류: [📎 서류 N건 열람/공유 &gt;]</code> 버튼 제공</li><li><strong>전용 서류 바텀시트 (<code>PersonDocumentSheet</code>)</strong>: <ul><li>인력의 제출 서류 목록과 검증 통계(<code>전체</code>, <code>검증완료</code>, <code>확인대기</code>)를 한눈에 파악</li></ul></li><li><strong>원클릭 열람 (<code>open_filex</code>)</strong>: 서류 카드의 <code>[열람]</code> 버튼 터치 시 기기 기본 PDF 뷰어 또는 이미지 뷰어로 즉시 열람</li><li><strong>네이티브 공유 (<code>share_plus</code>)</strong>: <code>[공유]</code> 버튼 터치 시 카카오톡, 문자, 이메일 등 모바일 기본 공유 시트를 통해 세무사나 본사 담당자에게 다이렉트 전송</li><li><strong>현장 검증 토글</strong>: 현장 실사 후 모바일 화면에서 직접 <code>[검증]</code> / <code>[검증취소]</code> 처리 가능</li></ul>',28)])])}const m=e(i,[["render",a]]);export{h as __pageData,m as default};
